@dataclass(frozen=True, slots=True)
class Money:
    minor: int
    currency: str

    def __post_init__(self) -> None:
        assert self.minor >= 0                    # canonical value only

    def __add__(self, other: "Money") -> "Money":   # closed: Money + Money -> Money
        if self.currency != other.currency: raise ValueError("currency mismatch")
        return Money(self.minor + other.minor, self.currency)

    def __mul__(self, factor: int) -> "Money":   # half-closed: scalar factor
        return Money(self.minor * factor, self.currency)
